css:
.loader { display: flex; flex-direction: column; gap: calc(var(--loader-size) * .05); width: var(--loader-size); }
.loader .row { display: flex; gap: calc(var(--loader-size) * .04); }
.loader .row i { flex: 1; height: calc(var(--loader-size) * .06); border-radius: calc(var(--loader-size) * .015); background: color-mix(in srgb, var(--loader-color) 30%, transparent); animation: twCell calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader .row i:first-child { flex: .45; }
.loader .row:nth-child(2) i { animation-delay: calc(var(--loader-speed) * .2); }
.loader .row:nth-child(3) i { animation-delay: calc(var(--loader-speed) * .4); }
@keyframes twCell { 0%, 100% { opacity: .3; } 50% { opacity: 1; } }

